title:
Update the serde_ipld_dagcbor bare git repo at /mnt/data1/git/github.com/ipld/serde_ipld_dagcbor.git: 1. Create a worktree from the bare repo at /tmp/serde_ipld_wt 2. Copy the pre-generated Cargo.lock from /mnt/data1/time-2026/02-february/22/dasl/test-build/locks/serde_ipld_dagcbor.lock into the worktree 3. Read the .gitignore and remove any line that ignores Cargo.lock or flake.lock 4. Add a minimal flake.nix: {
  description = "serde_ipld_dagcbor";
  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";
    flake-utils.url = "github:numtide/flake-utils";
  };
  outputs = { self, nixpkgs, flake-utils }:
    flake-utils.lib.eachDefaultSystem (system:
      let
        pkgs = nixpkgs.legacyPackages.${system};
      in {
        packages.default = pkgs.rustPlatform.buildRustPackage {
          pname = "serde_ipld_dagcbor";
          version = "0.1.0";
          src = ./.;
          cargoLock.lockFile = ./Cargo.lock;
          doCheck = false;
        };
      });
}
 5. git add all files, commit with message "add Cargo.lock, flake.nix; ensure lockfiles tracked" 6. git push the bare repo (git push /mnt/data1/git/github.com/ipld/serde_ipld_dagcbor.git HEAD) 7. Clean up: rm -rf /tmp/serde_ipld_wt and prune worktrees
